const fs = require('fs');
const path = require('path');

const README_PATH = path.join(__dirname, 'README.md');
const INDEX_PATH = path.join(__dirname, 'INDEX.md');

const headings = fs
  .readFileSync(README_PATH, 'utf8')
  .split(/\r?\n/)
  .filter((line) => line.startsWith('#'))
  .map((line) => line.trimEnd());

fs.writeFileSync(INDEX_PATH, headings.join('\n') + '\n');

console.log(`Wrote ${headings.length} headings to ${path.basename(INDEX_PATH)}`);

